// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';


export type BirdFlightProps = Record<string, any>;

const BirdFlight: React.FC<BirdFlightProps> = ({
  backgroundColor = "#87ceeb",
  transparentBackground = false,
  durationInSeconds = 6,
  birdColor = "#ffffff",
  birdScale = 1.5,
  wingFlapSpeed = 0.35,
  flightPath = "Sine Wave",
  showClouds = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety logic for transparent background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Calculate exact duration to guarantee monotonic interpolations
  const durationInFrames = Math.max(1, durationInSeconds * fps);
  
  // Normalized progress from 0 to 1 over the full duration
  const progress = interpolate(frame, [0, durationInFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Flap Scale oscillates between -1 (wing down) and 1 (wing up) deterministically
  const flapScale = Math.sin(frame * wingFlapSpeed);

  // X-Axis Positioning: Start completely off-screen left, end completely off-screen right
  const padding = 200 * birdScale;
  const totalDx = width + padding * 2;
  const startX = -padding;
  const endX = width + padding;
  
  const xPos = interpolate(progress, [0, 1], [startX, endX]);

  // Y-Axis Positioning & Rotation Logic
  let yPos = height * 0.5;
  let rotation = 0;

  // The derivative of X with respect to progress (constant velocity horizontally)
  const dxDp = totalDx;

  if (flightPath === "Sine Wave") {
    // Generate a smooth sine wave path across the screen
    const amplitude = height * 0.15;
    const frequency = Math.PI * 4; // 2 full waves across the screen
    
    yPos = height * 0.5 + Math.sin(progress * frequency) * amplitude;

    // Calculate tangent angle for rotation to follow the curve accurately
    const dyDp = amplitude * frequency * Math.cos(progress * frequency);
    rotation = Math.atan2(dyDp, dxDp) * (180 / Math.PI);
    
  } else if (flightPath === "Ascending") {
    // Linear path from bottom-ish to top-ish
    yPos = interpolate(progress, [0, 1], [height * 0.8, height * 0.2]);
    
    // Constant angle based on delta Y and delta X
    const dyDp = height * 0.2 - height * 0.8;
    rotation = Math.atan2(dyDp, dxDp) * (180 / Math.PI);
  }

  // Slight vertical bobbing synced with the wings to add weight
  const bobbingY = interpolate(flapScale, [-1, 1], [-8, 8]) * birdScale;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Background Clouds */}
      {showClouds && (
        <AbsoluteFill>
          {[0, 1, 2, 3, 4, 5].map((i) => {
            // Deterministic, stateless pseudo-random positioning for anti-flicker
            const pseudoRandomX = (i * 137.5) % width;
            const pseudoRandomY = (i * 93.1) % (height * 0.5);
            const speedMultiplier = 1 + (i % 3) * 0.4;
            const cloudScale = 0.5 + (i % 3) * 0.3;
            
            // Move clouds slightly to the left relative to frame
            const cloudX = pseudoRandomX - (frame * speedMultiplier);
            // Loop seamlessly
            const wrappedX = ((cloudX % (width + 400)) + (width + 400)) % (width + 400) - 200;

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: wrappedX,
                  top: pseudoRandomY,
                  opacity: 0.6,
                  transform: `scale(${cloudScale})`,
                  transition: "none",
                }}
              >
                <svg width="200" height="100" viewBox="0 0 200 100" fill="#ffffff" style={{ opacity: 0.7 }}>
                  <path d="M 50 60 C 50 40 70 30 85 40 C 100 20 130 20 145 40 C 160 30 180 40 180 60 L 50 60 Z" />
                </svg>
              </div>
            );
          })}
        </AbsoluteFill>
      )}

      {/* Bird Wrapper */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          transform: `translate(${xPos}px, ${yPos + bobbingY}px) rotate(${rotation}deg) scale(${birdScale})`,
          transformOrigin: "center center",
          transition: "none",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          width: 100,
          height: 100,
          marginLeft: -50,
          marginTop: -50,
        }}
      >
        <svg
          width="100"
          height="100"
          viewBox="0 0 100 100"
          style={{ overflow: "visible" }}
        >
          <defs>
            <filter id="bird-shadow" x="-30%" y="-30%" width="160%" height="160%">
              <feDropShadow dx="0" dy="15" stdDeviation="8" floodColor="#000000" floodOpacity="0.15" />
            </filter>
          </defs>

          <g filter="url(#bird-shadow)">
            {/* Back Wing (Flaps opposite/slightly offset visually by scale inversion) */}
            <g style={{ transformOrigin: "50px 50px", transform: `scaleY(${-flapScale * 0.8})` }}>
              <path d="M 45 48 C 55 5 80 10 75 48 Z" fill={birdColor} opacity={0.6} />
            </g>

            {/* Tail */}
            <path d="M 12 48 L 30 50 L 12 52 Z" fill={birdColor} />

            {/* Main Body */}
            <path d="M 25 50 C 35 40 75 42 90 50 C 75 58 35 60 25 50 Z" fill={birdColor} />

            {/* Front Wing */}
            <g style={{ transformOrigin: "50px 50px", transform: `scaleY(${flapScale})` }}>
              <path d="M 38 52 C 48 0 88 5 82 52 Z" fill={birdColor} />
            </g>
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default BirdFlight;